    assert 'negative' in str(e), str(e)

ex.sol:
def parse_hours(raw: str) -> float:
    try:
        h = float(raw)
    except ValueError:
        raise ValueError(f'Hours must be a number, got {raw!r}') from None
    if h < 0:
        raise ValueError("Hours can't be negative")
    return h

tests:
try:
    list(chunks(['a'], 2, 2)); raise AssertionError('should raise')
except ValueError:
    pass

ex.sol:
def chunks(words, size, overlap):
    if overlap >= size:
        raise ValueError('overlap must be smaller than size')
    step = size - overlap
    for start in range(0, len(words), step):
        yield words[start:start + size]
        if start + size >= len(words):
            break

